  1	name = "multiplayer-dg-sync"
  2	main = "worker/worker.ts"
  3	compatibility_date = "2024-07-01"
  4	
  5	[dev]
  6	port = 5172
  7	ip = "0.0.0.0"
  8	
  9	# Set up the durable object used for each tldraw room
 10	[durable_objects]
 11	bindings = [
 12	    { name = "TLDRAW_DURABLE_OBJECT", class_name = "TldrawDurableObject" },
 13	]
 14	
 15	# Durable objects require migrations to create/modify/delete them
 16	[[migrations]]
 17	tag = "v1"
 18	new_sqlite_classes = ["TldrawDurableObject"]
 19	
 20	# We store room snapshots (assests are stored in native apps) in an R2 bucket
 21	[[r2_buckets]]
 22	binding = 'TLDRAW_BUCKET'
 23	bucket_name = 'tldraw-content'
 24	preview_bucket_name = 'tldraw-content-preview'
  1	{
