  1	import { RoomSnapshot, TLSocketRoom } from "@tldraw/sync-core";
  2	import {
  3	  TLRecord,
  4	  createTLSchema,
  5	  defaultBindingSchemas,
  6	  defaultShapeSchemas,
  7	} from "@tldraw/tlschema";
  8	import { AutoRouter, IRequest, error } from "itty-router";
  9	import throttle from "lodash.throttle";
 10	import { Environment } from "./types";
 11	
 12	type RoomSchemaConfig = {
 13	  shapeTypes: string[];
 14	  bindingTypes: string[];
 15	};
 16	
 17	const STORAGE_SCHEMA_CONFIG_KEY = "schemaConfig";
 18	
 19	const createRoomSchema = ({ shapeTypes, bindingTypes }: RoomSchemaConfig) => {
 20	  const customShapeSchemas = Object.fromEntries(
 21	    shapeTypes.map((type) => [type, {}]),
 22	  );
 23	  const customBindingSchemas = Object.fromEntries(
 24	    bindingTypes.map((type) => [type, {}]),
 25	  );
 26	
 27	  return createTLSchema({
 28	    shapes: {
 29	      ...defaultShapeSchemas,
 30	      ...customShapeSchemas,
 31	    },
 32	    bindings: {
 33	      ...defaultBindingSchemas,
 34	      ...customBindingSchemas,
 35	    },
 36	  });
 37	};
 38	
 39	const dedupeAndSort = (values: string[]): string[] => {
 40	  return Array.from(new Set(values.filter(Boolean))).sort((a, b) =>
 41	    a.localeCompare(b),
 42	  );
 43	};
 44	
 45	const mergeSchemaConfig = (
 46	  baseConfig: RoomSchemaConfig,
 47	  incomingConfig: RoomSchemaConfig,
 48	): RoomSchemaConfig => ({
 49	  shapeTypes: dedupeAndSort(
 50	    baseConfig.shapeTypes.concat(incomingConfig.shapeTypes),
 51	  ),
 52	  bindingTypes: dedupeAndSort(
 53	    baseConfig.bindingTypes.concat(incomingConfig.bindingTypes),
 54	  ),
 55	});
 56	
 57	const isSameSchemaConfig = (
 58	  a: RoomSchemaConfig,
 59	  b: RoomSchemaConfig,
 60	): boolean => {
 61	  return (
 62	    a.shapeTypes.length === b.shapeTypes.length &&
 63	    a.bindingTypes.length === b.bindingTypes.length &&
 64	    a.shapeTypes.every((value, index) => value === b.shapeTypes[index]) &&
 65	    a.bindingTypes.every((value, index) => value === b.bindingTypes[index])
 66	  );
 67	};
 68	
 69	// each whiteboard room is hosted in a DurableObject:
 70	// https://developers.cloudflare.com/durable-objects/
 71	
 72	// there's only ever one durable object instance per room. it keeps all the room state in memory and
 73	// handles websocket connections. periodically, it persists the room state to the R2 bucket.
 74	export class TldrawDurableObject {
 75	  private r2: R2Bucket;
 76	  // the room ID will be missing whilst the room is being initialized
 77	  private roomId: string | null = null;
 78	  private roomSchemaConfig: RoomSchemaConfig = {
 79	    shapeTypes: [],
 80	    bindingTypes: [],
 81	  };
 82	  // when we load the room from the R2 bucket, we keep it here. it's a promise so we only ever
 83	  // load it once.
 84	  private roomPromise: Promise<TLSocketRoom<TLRecord, void>> | null = null;
 85	
 86	  constructor(
 87	    private readonly ctx: DurableObjectState,
 88	    env: Environment,
 89	  ) {
 90	    this.r2 = env.TLDRAW_BUCKET;
 91	
 92	    ctx.blockConcurrencyWhile(async () => {
 93	      this.roomId = ((await this.ctx.storage.get("roomId")) ?? null) as
 94	        | string
 95	        | null;
 96	      const schemaConfig =
 97	        ((await this.ctx.storage.get(
 98	          STORAGE_SCHEMA_CONFIG_KEY,
 99	        )) as RoomSchemaConfig) ?? null;
100	      if (schemaConfig) {
101	        this.roomSchemaConfig = {
102	          shapeTypes: dedupeAndSort(schemaConfig.shapeTypes ?? []),
103	          bindingTypes: dedupeAndSort(schemaConfig.bindingTypes ?? []),
104	        };
105	      }
106	    });
107	  }
108	
109	  private readonly router = AutoRouter({
110	    catch: (e) => {
111	      console.log(e);
112	      return error(e);
113	    },
114	  })
115	    // when we get a connection request, we stash the room id if needed and handle the connection
116	    .get("/connect/:roomId", async (request) => {
117	      if (!this.roomId) {
118	        await this.ctx.blockConcurrencyWhile(async () => {
119	          await this.ctx.storage.put("roomId", request.params.roomId);
120	          this.roomId = request.params.roomId;
121	        });
122	      }
123	      return this.handleConnect(request);
124	    });
125	
126	  // `fetch` is the entry point for all requests to the Durable Object
127	  fetch(request: Request): Response | Promise<Response> {
128	    return this.router.fetch(request);
129	  }
130	
131	  // what happens when someone tries to connect to this room?
132	  async handleConnect(request: IRequest): Promise<Response> {
133	    // extract query params from request
134	    const sessionId = request.query.sessionId as string;
135	    if (!sessionId) return error(400, "Missing sessionId");
136	    const incomingSchemaConfig = this.getIncomingSchemaConfig(request);
137	    await this.ensureSchemaConfig(incomingSchemaConfig);
138	
139	    // Create the websocket pair for the client
140	    const { 0: clientWebSocket, 1: serverWebSocket } = new WebSocketPair();
141	    serverWebSocket.accept();
142	
143	    // load the room, or retrieve it if it's already loaded
144	    const room = await this.getRoom();
145	
146	    // connect the client to the room
147	    room.handleSocketConnect({ sessionId, socket: serverWebSocket });
148	
149	    // return the websocket connection to the client
150	    return new Response(null, { status: 101, webSocket: clientWebSocket });
151	  }
152	
153	  private getIncomingSchemaConfig(request: IRequest): RoomSchemaConfig {
154	    const url = new URL(request.url);
155	    return {
156	      shapeTypes: dedupeAndSort(url.searchParams.getAll("shapeType")),
157	      bindingTypes: dedupeAndSort(url.searchParams.getAll("bindingType")),
158	    };
159	  }
160	
161	  private async ensureSchemaConfig(
162	    incomingSchemaConfig: RoomSchemaConfig,
163	  ): Promise<void> {
164	    const nextConfig = mergeSchemaConfig(
165	      this.roomSchemaConfig,
166	      incomingSchemaConfig,
167	    );
168	    if (isSameSchemaConfig(this.roomSchemaConfig, nextConfig)) return;
169	
170	    this.roomSchemaConfig = nextConfig;
171	    await this.ctx.storage.put(
172	      STORAGE_SCHEMA_CONFIG_KEY,
173	      this.roomSchemaConfig,
174	    );
175	
176	    if (this.roomPromise) {
177	      const previousRoom = await this.roomPromise;
178	      const snapshot = previousRoom.getCurrentSnapshot();
179	      previousRoom.close();
180	      this.roomPromise = Promise.resolve(this.createRoom(snapshot));
181	    }
182	  }
183	
184	  private createRoom(
185	    initialSnapshot?: RoomSnapshot,
186	  ): TLSocketRoom<TLRecord, void> {
187	    return new TLSocketRoom<TLRecord, void>({
188	      schema: createRoomSchema(this.roomSchemaConfig),
189	      initialSnapshot,
190	      onDataChange: () => {
191	        // and persist whenever the data in the room changes
192	        this.schedulePersistToR2();
193	      },
194	    });
195	  }
196	
197	  getRoom() {
198	    const roomId = this.roomId;
199	    if (!roomId) throw new Error("Missing roomId");
200	
201	    if (!this.roomPromise) {
202	      this.roomPromise = (async () => {
203	        // fetch the room from R2
204	        const roomFromBucket = await this.r2.get(`rooms/${roomId}`);
205	
206	        // if it doesn't exist, we'll just create a new empty room
207	        const initialSnapshot = roomFromBucket
208	          ? ((await roomFromBucket.json()) as RoomSnapshot)
209	          : undefined;
210	
211	        // create a new TLSocketRoom. This handles all the sync protocol & websocket connections.
212	        // it's up to us to persist the room state to R2 when needed though.
213	        return this.createRoom(initialSnapshot);
214	      })();
215	    }
216	
217	    return this.roomPromise;
218	  }
219	
220	  // we throttle persistance so it only happens every 10 seconds
221	  schedulePersistToR2: () => void = throttle(async () => {
222	    if (!this.roomPromise || !this.roomId) return;
223	    try {
224	      const room = await this.getRoom();
225	      const snapshot = JSON.stringify(room.getCurrentSnapshot());
226	      await this.r2.put(`rooms/${this.roomId}`, snapshot);
227	    } catch (e) {
228	      console.error("Failed to persist room to R2", {
229	        roomId: this.roomId,
230	        error: e,
231	      });
232	    }
233	  }, 10_000);
234	}
  1	// the contents of the environment should mostly be determined by wrangler.toml. These entries match
  2	// the bindings defined there.
  3	export interface Environment {
  4	  TLDRAW_BUCKET: R2Bucket;
  5	  TLDRAW_DURABLE_OBJECT: DurableObjectNamespace;
  6	}
  1	import { handleUnfurlRequest } from "cloudflare-workers-unfurl";
  2	import { AutoRouter, error, IRequest } from "itty-router";
  3	import { Environment } from "./types";
  4	
  5	// make sure our sync durable object is made available to cloudflare
  6	export { TldrawDurableObject } from "./TldrawDurableObject";
  7	
  8	const ALLOWED_ORIGINS = [
  9	  "https://roamresearch.com",
 10	  "http://localhost:3000",
 11	  "app://obsidian.md",
 12	];
 13	
 14	const isVercelPreviewUrl = (origin: string): boolean =>
 15	  /^https:\/\/.*-discourse-graph-[a-z0-9]+\.vercel\.app$/.test(origin);
 16	
 17	const isAllowedOrigin = (origin: string): boolean =>
 18	  ALLOWED_ORIGINS.some((allowedOrigin) => origin === allowedOrigin) ||
 19	  isVercelPreviewUrl(origin);
 20	
 21	const setCorsHeaders = ({
 22	  request,
 23	  response,
 24	}: {
 25	  request: IRequest;
 26	  response: Response;
 27	}): Response => {
 28	  if (response.status === 101) return response; // WebSocket upgrade response; headers are immutable here, so skip CORS header mutation.
 29	
 30	  const origin = request.headers.get("origin");
 31	  if (origin && isAllowedOrigin(origin)) {
 32	    response.headers.set("Access-Control-Allow-Origin", origin);
 33	    response.headers.set("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
 34	    response.headers.set(
 35	      "Access-Control-Allow-Headers",
 36	      "Content-Type, Authorization, x-vercel-protection-bypass",
 37	    );
 38	  }
 39	  return response;
 40	};
 41	
 42	const handlePreflight = (request: IRequest): Response => {
 43	  const origin = request.headers.get("origin");
 44	  if (!origin || !isAllowedOrigin(origin)) {
 45	    return error(403, "Origin not allowed");
 46	  }
 47	
 48	  return new Response(null, {
 49	    status: 204,
 50	    headers: {
 51	      "Access-Control-Allow-Origin": origin,
 52	      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
 53	      "Access-Control-Allow-Headers":
 54	        "Content-Type, Authorization, x-vercel-protection-bypass",
 55	      "Access-Control-Max-Age": "86400",
 56	    },
 57	  });
 58	};
 59	
 60	const enforceAllowedOrigin = (request: IRequest): Response | void => {
 61	  if (request.method === "OPTIONS") return;
 62	  const origin = request.headers.get("origin");
 63	  if (origin && !isAllowedOrigin(origin)) {
 64	    return error(403, "Origin not allowed");
 65	  }
 66	};
 67	
 68	const router = AutoRouter<IRequest, [env: Environment, ctx: ExecutionContext]>({
 69	  before: [enforceAllowedOrigin],
 70	  catch: (e) => {
 71	    console.error(e);
 72	    return error(e);
 73	  },
 74	})
 75	  .options("*", handlePreflight)
 76	  // requests to /connect are routed to the Durable Object, and handle realtime websocket syncing
 77	  .get("/connect/:roomId", async (request, env) => {
 78	    const id = env.TLDRAW_DURABLE_OBJECT.idFromName(request.params.roomId);
 79	    const room = env.TLDRAW_DURABLE_OBJECT.get(id);
 80	    const response = await room.fetch(request.url, {
 81	      headers: request.headers,
 82	      body: request.body,
 83	    });
 84	    return setCorsHeaders({ request, response });
 85	  })
 86	
 87	  // bookmarks need to extract metadata from pasted URLs:
 88	  .get("/unfurl", async (request) => {
 89	    const response = await handleUnfurlRequest(request);
 90	    return setCorsHeaders({ request, response });
 91	  });
 92	
 93	// export our router for cloudflare
 94	export default router;

  1	import { useSync } from "@tldraw/sync";
  2	import {
  3	  TLAnyBindingUtilConstructor,
  4	  TLAnyShapeUtilConstructor,
  5	  TLAssetStore,
  6	  TLStoreWithStatus,
  7	  defaultBindingUtils,
  8	  defaultShapeUtils,
  9	  MigrationSequence,
 10	} from "tldraw";
 11	import { useMemo } from "react";
 12	import { getCurrentRoamTldrawUserInfo } from "~/utils/roamTldrawUserInfo";
 13	
 14	/** Base URL for tldraw-sync-cloudflare worker. Use https (not wss) - useSync upgrades to WebSocket. */
 15	export const TLDRAW_CLOUDFLARE_SYNC_WS_BASE_URL =
 16	  "https://multiplayer-dg-sync.discoursegraphs.workers.dev";
 17	
 18	export type CloudflareCanvasStoreAdapterResult = {
 19	  store: TLStoreWithStatus;
 20	  error: Error | null;
 21	  isLoading: boolean;
 22	};
 23	
 24	// TODO: this should be more secure, but using graphName/UID is probably fine for now
 25	export const getSyncRoomId = ({ pageUid }: { pageUid: string }): string => {
 26	  const graphName = window.roamAlphaAPI.graph.name;
 27	  const payload = JSON.stringify({ graphName, pageUid });
 28	  const bytes = new TextEncoder().encode(payload);
 29	  let binary = "";
 30	  for (const byte of bytes) {
 31	    binary += String.fromCharCode(byte);
 32	  }
 33	
 34	  return btoa(binary)
 35	    .replace(/\+/g, "-")
 36	    .replace(/\//g, "_")
 37	    .replace(/=+$/g, "");
 38	};
 39	
 40	const parseRoamUploadResponse = (value: string): string => {
 41	  return value.replace(/^!\[\]\(/, "").replace(/\)$/, "");
 42	};
 43	
 44	const createRoamAssetStore = (): TLAssetStore => {
 45	  return {
 46	    upload: async (_asset, file) => {
 47	      const response = await window.roamAlphaAPI.file.upload({ file });
 48	      return parseRoamUploadResponse(response);
 49	    },
 50	    resolve: (asset) => asset.props.src,
 51	  };
 52	};
 53	
 54	export const useCloudflareSyncStore = ({
 55	  pageUid,
 56	  migrations,
 57	  customShapeUtils,
 58	  customBindingUtils,
 59	  customShapeTypes,
 60	  customBindingTypes,
 61	}: {
 62	  pageUid: string;
 63	  migrations: MigrationSequence[];
 64	  customShapeUtils: readonly TLAnyShapeUtilConstructor[];
 65	  customBindingUtils: readonly TLAnyBindingUtilConstructor[];
 66	  customShapeTypes: string[];
 67	  customBindingTypes: string[];
 68	}): CloudflareCanvasStoreAdapterResult => {
 69	  const assets = useMemo(() => createRoamAssetStore(), []);
 70	  const shapeUtils = useMemo(
 71	    () => [...defaultShapeUtils, ...customShapeUtils],
 72	    [customShapeUtils],
 73	  );
 74	  const bindingUtils = useMemo(
 75	    () => [...defaultBindingUtils, ...customBindingUtils],
 76	    [customBindingUtils],
 77	  );
 78	  const userInfo = useMemo(() => getCurrentRoamTldrawUserInfo(), []);
 79	
 80	  const uri = useMemo(() => {
 81	    const roomId = getSyncRoomId({ pageUid });
 82	    const query = new URLSearchParams();
 83	    for (const shapeType of customShapeTypes) {
 84	      query.append("shapeType", shapeType);
 85	    }
 86	    for (const bindingType of customBindingTypes) {
 87	      query.append("bindingType", bindingType);
 88	    }
 89	    return `${TLDRAW_CLOUDFLARE_SYNC_WS_BASE_URL}/connect/${roomId}?${query.toString()}`;
 90	  }, [customShapeTypes, customBindingTypes, pageUid]);
 91	
 92	  const store = useSync({
 93	    uri,
 94	    assets,
 95	    migrations,
 96	    shapeUtils,
 97	    bindingUtils,
 98	    userInfo,
 99	  });
100	
101	  return {
102	    store,
103	    error: store.status === "error" ? store.error : null,
104	    isLoading: store.status === "loading",
105	  };
106	};
  1	import getBlockProps, { json } from "~/utils/getBlockProps";
  2	import setBlockProps from "~/utils/setBlockProps";
  3	import {
  4	  TLAnyBindingUtilConstructor,
  5	  TLAnyShapeUtilConstructor,
  6	  TLStore,
  7	  TLStoreWithStatus,
  8	  MigrationSequence,
  9	  loadSnapshot,
 10	} from "tldraw";
 11	import { getRoamCanvasSnapshot } from "./useRoamStore";
 12	import { withAutoCanvasRelationsSuppressed } from "./autoCanvasRelationsSuppression";
 13	
 14	export type CanvasSyncMode = "local" | "sync";
 15	export type CanvasSyncMigrationState = "pending" | "done";
 16	
 17	const QUERY_BUILDER_PROP_KEY = "roamjs-query-builder";
 18	const CANVAS_SYNC_MODE_KEY = "canvasSyncMode";
 19	const CANVAS_SYNC_MIGRATION_STATE_KEY = "canvasSyncMigrationState";
 20	const DEFAULT_CANVAS_SYNC_MODE: CanvasSyncMode = "local";
 21	
 22	const isCanvasSyncMode = (value: unknown): value is CanvasSyncMode =>
 23	  value === "local" || value === "sync";
 24	
 25	const isCanvasSyncMigrationState = (
 26	  value: unknown,
 27	): value is CanvasSyncMigrationState => value === "pending" || value === "done";
 28	
 29	const getRoamJsQueryBuilderProps = (pageUid: string): Record<string, json> => {
 30	  const props = getBlockProps(pageUid);
 31	  const value = props[QUERY_BUILDER_PROP_KEY];
 32	  if (value && typeof value === "object" && !Array.isArray(value)) {
 33	    return value;
 34	  }
 35	  return {};
 36	};
 37	
 38	const setRoamJsQueryBuilderProps = ({
 39	  pageUid,
 40	  nextRjsqb,
 41	}: {
 42	  pageUid: string;
 43	  nextRjsqb: Record<string, json>;
 44	}): void => {
 45	  setBlockProps(pageUid, {
 46	    [QUERY_BUILDER_PROP_KEY]: nextRjsqb,
 47	  });
 48	};
 49	
 50	const updateCanvasSyncProps = ({
 51	  pageUid,
 52	  updates,
 53	}: {
 54	  pageUid: string;
 55	  updates: Partial<
 56	    Record<
 57	      typeof CANVAS_SYNC_MODE_KEY | typeof CANVAS_SYNC_MIGRATION_STATE_KEY,
 58	      json
 59	    >
 60	  >;
 61	}): void => {
 62	  const rjsqb = getRoamJsQueryBuilderProps(pageUid);
 63	  setRoamJsQueryBuilderProps({
 64	    pageUid,
 65	    nextRjsqb: {
 66	      ...rjsqb,
 67	      ...updates,
 68	    },
 69	  });
 70	};
 71	
 72	export const getPersistedCanvasSyncMode = ({
 73	  pageUid,
 74	}: {
 75	  pageUid: string;
 76	}): CanvasSyncMode | null => {
 77	  const rjsqb = getRoamJsQueryBuilderProps(pageUid);
 78	  const mode = rjsqb[CANVAS_SYNC_MODE_KEY];
 79	  return isCanvasSyncMode(mode) ? mode : null;
 80	};
 81	
 82	export const getEffectiveCanvasSyncMode = ({
 83	  pageUid,
 84	}: {
 85	  pageUid: string;
 86	}): CanvasSyncMode => {
 87	  return getPersistedCanvasSyncMode({ pageUid }) ?? DEFAULT_CANVAS_SYNC_MODE;
 88	};
 89	
 90	export const setCanvasSyncMode = ({
 91	  pageUid,
 92	  mode,
 93	}: {
 94	  pageUid: string;
 95	  mode: CanvasSyncMode;
 96	}): void => {
 97	  updateCanvasSyncProps({
