177	export const migrateLocalCanvasToCloud = ({
178	  pageUid,
179	  store,
180	  migrations,
181	  customShapeUtils,
182	  customBindingUtils,
183	}: {
184	  pageUid: string;
185	  store: TLStore;
186	  migrations: MigrationSequence[];
187	  customShapeUtils: readonly TLAnyShapeUtilConstructor[];
188	  customBindingUtils: readonly TLAnyBindingUtilConstructor[];
189	}): { migrated: boolean; migrationState: CanvasSyncMigrationState } => {
190	  if (getShapeRecordCount(store) > 0) {
191	    setCanvasSyncSettings({
192	      pageUid,
193	      mode: "sync",
194	      migrationState: "done",
195	    });
196	    return {
197	      migrated: false,
198	      migrationState: "done",
199	    };
200	  }
201	
202	  const localSnapshot = getRoamCanvasSnapshot({
203	    pageUid,
204	    migrations,
205	    customShapeUtils,
206	    customBindingUtils,
207	    includePersonalRecords: false,
208	  });
209	
210	  if (!localSnapshot) {
211	    setCanvasSyncSettings({
212	      pageUid,
213	      mode: "sync",
214	      migrationState: "done",
215	    });
216	    return {
217	      migrated: false,
218	      migrationState: "done",
219	    };
220	  }
221	
222	  // Loading a local snapshot into the cloud store replays shape creation.
223	  // Suppress auto-generated relations so migration copies the canvas exactly
224	  // instead of creating duplicate relation shapes for imported nodes.
225	  withAutoCanvasRelationsSuppressed(() => loadSnapshot(store, localSnapshot));
226	
227	  setCanvasSyncSettings({
228	    pageUid,
229	    mode: "sync",
230	    migrationState: "done",
231	  });
232	
233	  return {
234	    migrated: true,
235	    migrationState: "done",
236	  };
237	};
