    27	const getRecordType = (record: unknown): string | undefined => {
    28	  if (typeof record !== "object" || record === null) return undefined;
    29	  const candidate = (record as { type?: unknown }).type;
    30	  return typeof candidate === "string" ? candidate : undefined;
    31	};
    32	
    33	const getRecordTypeName = (record: unknown): string | undefined => {
    34	  if (typeof record !== "object" || record === null) return undefined;
    35	  const candidate = (record as { typeName?: unknown }).typeName;
    36	  return typeof candidate === "string" ? candidate : undefined;
    37	};
    38	
    39	const hasArrowLikeProps = (record: unknown): boolean => {
    40	  if (typeof record !== "object" || record === null) return false;
    41	  const props = (record as { props?: unknown }).props;
    42	  if (typeof props !== "object" || props === null) return false;
    43	  return (
    44	    "start" in props &&
    45	    "end" in props &&
    46	    "arrowheadEnd" in props &&
    47	    ("bend" in props || "labelPosition" in props || "text" in props)
    48	  );
    49	};
    50	
    51	const isIgnoredArrowLikeShapeType = ({
    52	  recordType,
    53	  allNodeTypes,
    54	}: {
    55	  recordType: string;
    56	  allNodeTypes: string[];
    57	}): boolean => {
    58	  return (
    59	    recordType === "arrow" ||
    60	    recordType === DISCOURSE_RELATION_SHAPE_TYPE ||
    61	    recordType === DISCOURSE_NODE_SHAPE_TYPE ||
    62	    allNodeTypes.includes(recordType)
    63	  );
    64	};
    65	
    66	const isLegacyRelationOrReferencedShape = ({
    67	  record,
    68	  allRelationIds,
    69	  allAddReferencedNodeActions,
    70	  allNodeTypes,
    71	}: {
    72	  record: unknown;
    73	  allRelationIds: string[];
    74	  allAddReferencedNodeActions: string[];
    75	  allNodeTypes: string[];
    76	}): boolean => {
    77	  const recordType = getRecordType(record);
    78	  if (getRecordTypeName(record) !== "shape" || !recordType) return false;
    79	  if (
    80	    [...allRelationIds, ...allAddReferencedNodeActions].includes(recordType)
    81	  ) {
    82	    return true;
    83	  }
    84	  return (
    85	    hasArrowLikeProps(record) &&
    86	    !isIgnoredArrowLikeShapeType({ recordType, allNodeTypes })
    87	  );
    88	};
    89	
    90	const isLegacyCanonicalRelationShape = ({
    91	  record,
    92	  allRelationIds,
    93	  allAddReferencedNodeActions,
    94	  allNodeTypes,
    95	}: {
    96	  record: unknown;
    97	  allRelationIds: string[];
    98	  allAddReferencedNodeActions: string[];
    99	  allNodeTypes: string[];
   100	}): boolean => {
   101	  const recordType = getRecordType(record);
   102	  if (getRecordTypeName(record) !== "shape" || !recordType) return false;
   103	  if (allRelationIds.includes(recordType)) return true;
   104	  if (allAddReferencedNodeActions.includes(recordType)) return false;
   105	  return (
   106	    hasArrowLikeProps(record) &&
   107	    !isIgnoredArrowLikeShapeType({ recordType, allNodeTypes })
   108	  );
   109	};
