   111	export const migrateRelationTypesToDiscourseRelation = ({
   112	  oldStore,
   113	  allRelationIds,
   114	  allAddReferencedNodeActions,
   115	  allNodeTypes,
   116	}: {
   117	  oldStore: Record<string, any>;
   118	  allRelationIds: string[];
   119	  allAddReferencedNodeActions: string[];
   120	  allNodeTypes: string[];
   121	}): void => {
   122	  const migratedRelationTypeIdsByShapeId = new Map<TLShapeId, string>();
   123	
   124	  for (const record of Object.values(oldStore)) {
   125	    if (
   126	      !isLegacyCanonicalRelationShape({
   127	        record,
   128	        allRelationIds,
   129	        allAddReferencedNodeActions,
   130	        allNodeTypes,
   131	      })
   132	    ) {
   133	      continue;
   134	    }
   135	
   136	    const shape = record;
   137	    const relationTypeId = shape.props?.relationTypeId || shape.type;
   138	    if (!shape.props) shape.props = {};
   139	    shape.props.relationTypeId = relationTypeId;
   140	    shape.type = DISCOURSE_RELATION_SHAPE_TYPE;
   141	    migratedRelationTypeIdsByShapeId.set(shape.id, relationTypeId);
   142	  }
   143	
   144	  for (const record of Object.values(oldStore)) {
   145	    if (getRecordTypeName(record) !== "binding") continue;
   146	
   147	    const binding = record as RelationBinding;
   148	    if (!migratedRelationTypeIdsByShapeId.has(binding.fromId)) {
   149	      continue;
   150	    }
   151	    binding.type = DISCOURSE_RELATION_SHAPE_TYPE;
   152	  }
   153	};
