   155	export const createMigrations = ({
   156	  allRelationIds,
   157	  allAddReferencedNodeActions,
   158	  allNodeTypes,
   159	}: {
   160	  allRelationIds: string[];
   161	  allAddReferencedNodeActions: string[];
   162	  allNodeTypes: string[];
   163	}) => {
   164	  const versions = createMigrationIds(`${SEQUENCE_ID_BASE}`, {
   165	    ExtractBindings: 1,
   166	    "2.3.0": 2,
   167	    AddSizeAndFontFamily: 3,
   168	    RemoveNullAssetFileSize: 4,
   169	    MigrateNodeTypeToDiscourseNode: 5,
   170	    MigrateRelationTypeToDiscourseRelation: 6,
   171	  });
   172	  return createMigrationSequence({
   173	    sequenceId: `${SEQUENCE_ID_BASE}`,
   174	    sequence: [
   175	      {
   176	        id: versions["ExtractBindings"],
   177	        scope: "store",
   178	        up: (oldStore) => {
   179	          type OldArrowTerminal =
   180	            | { type: "point"; x: number; y: number }
   181	            | {
   182	                type: "binding";
   183	                boundShapeId: TLShapeId;
   184	                normalizedAnchor: VecModel;
   185	                isExact: boolean;
   186	                isPrecise: boolean;
   187	              }
   188	            // new type:
   189	            | { type?: undefined; x: number; y: number };
   190	
   191	          type OldArrow = TLBaseShape<
   192	            string,
   193	            { start: OldArrowTerminal; end: OldArrowTerminal }
   194	          >;
   195	
   196	          const arrows = Object.values(oldStore).filter((r): r is OldArrow => {
   197	            return isLegacyRelationOrReferencedShape({
   198	              record: r,
   199	              allRelationIds,
   200	              allAddReferencedNodeActions,
   201	              allNodeTypes,
   202	            });
   203	          });
   204	
   205	          for (const a of arrows) {
   206	            const arrow = a as unknown as OldArrow;
   207	            const { start, end } = arrow.props;
   208	
   209	            // TODO: do we have any that are not binding?
   210	            if (start.type === "binding") {
   211	              const id = createBindingId();
   212	              const binding: RelationBinding = {
   213	                typeName: "binding",
   214	                id,
   215	                type: arrow.type,
   216	                fromId: arrow.id,
   217	                toId: start.boundShapeId,
   218	                meta: {},
   219	                props: {
   220	                  terminal: "start",
   221	                  normalizedAnchor: start.normalizedAnchor,
   222	                  isExact: start.isExact || false,
   223	                  isPrecise: start.isPrecise || false,
   224	                },
   225	              };
   226	              oldStore[id] = binding;
   227	            } else {
   228	              delete arrow.props.start.type;
   229	            }
   230	
   231	            // TODO: do we have any that are not binding?
   232	            if (end.type === "binding") {
   233	              const id = createBindingId();
   234	              const binding: RelationBinding = {
   235	                typeName: "binding",
   236	                id,
   237	                type: arrow.type,
   238	                fromId: arrow.id,
   239	                toId: end.boundShapeId,
   240	                meta: {},
   241	                props: {
   242	                  terminal: "end",
   243	                  normalizedAnchor: end.normalizedAnchor,
   244	                  isExact: end.isExact || false,
   245	                  isPrecise: end.isPrecise || false,
   246	                },
   247	              };
   248	
   249	              oldStore[id] = binding;
   250	            } else {
   251	              delete arrow.props.end.type;
   252	            }
   253	          }
   254	        },
   255	      },
   256	      {
   257	        id: versions["2.3.0"],
   258	        scope: "record",
   259	        filter: (r: any) => {
   260	          return isLegacyRelationOrReferencedShape({
   261	            record: r,
   262	            allRelationIds,
   263	            allAddReferencedNodeActions,
   264	            allNodeTypes,
   265	          });
   266	        },
   267	        up: (arrow: any) => {
   268	          arrow.props.start = { x: 0, y: 0 };
   269	          arrow.props.end = { x: 0, y: 0 };
   270	          arrow.props.labelPosition = 0.5;
   271	          arrow.props.scale = 1;
   272	
   273	          const color = getRelationColor(arrow.props.text || "");
   274	          arrow.props.color = color;
   275	          arrow.props.labelColor = color;
   276	        },
   277	      },
   278	      {
   279	        id: versions["AddSizeAndFontFamily"],
   280	        scope: "record",
   281	        filter: (r: any) => {
   282	          const recordType = getRecordType(r);
   283	          return (
   284	            getRecordTypeName(r) === "shape" &&
   285	            !!recordType &&
   286	            allNodeTypes.includes(recordType)
   287	          );
   288	        },
   289	        up: (shape: any) => {
   290	          if (!shape.props.size) shape.props.size = "m";
   291	          if (!shape.props.fontFamily) shape.props.fontFamily = "draw";
   292	        },
   293	      },
   294	      {
   295	        id: versions["RemoveNullAssetFileSize"],
   296	        scope: "record",
   297	        filter: (r: any) =>
   298	          r.typeName === "asset" &&
   299	          (r.type === "image" || r.type === "video") &&
   300	          r.props?.fileSize === null,
   301	        up: (asset: any) => {
   302	          delete asset.props.fileSize;
   303	        },
   304	      },
   305	      {
   306	        id: versions["MigrateNodeTypeToDiscourseNode"],
   307	        scope: "record",
   308	        // Assumes node type ids and relation ids are distin
   309	        filter: (r: any) => {
   310	          const recordType = getRecordType(r);
   311	          return (
   312	            getRecordTypeName(r) === "shape" &&
   313	            !!recordType &&
   314	            allNodeTypes.includes(recordType)
