   316	        },
   317	        up: (shape: any) => {
   318	          shape.props.nodeTypeId = shape.type;
   319	          shape.type = DISCOURSE_NODE_SHAPE_TYPE;
   320	        },
   321	      },
   322	      {
   323	        id: versions["MigrateRelationTypeToDiscourseRelation"],
   324	        scope: "store",
   325	        up: (oldStore) => {
   326	          migrateRelationTypesToDiscourseRelation({
   327	            oldStore,
   328	            allRelationIds,
   329	            allAddReferencedNodeActions,
   330	            allNodeTypes,
   331	          });
   332	        },
   333	      },
   334	    ],
   335	  });
