export const isPageUid = (uid: string) =>
  !!window.roamAlphaAPI.pull("[:node/title]", [":block/uid", uid])?.[
    ":node/title"
  ];

export const TldrawCanvas = ({ title }: { title: string }) => {
  // In Roam, canvas identity is currently keyed by the page UID.
  // Room sync is graph/page encoded as an opaque base64url token.
  const pageUid = useMemo(() => getPageUidByPageTitle(title), [title]);
  const [canvasSyncMode, setCanvasSyncModeState] = useState<CanvasSyncMode>(
    () => getEffectiveCanvasSyncMode({ pageUid }),
  );

  const useCloudflareSync =
    canvasSyncMode === "sync" && !!TLDRAW_CLOUDFLARE_SYNC_WS_BASE_URL;

  useEffect(() => {
    setCanvasSyncModeState(ensureCanvasSyncMode({ pageUid }));
  }, [pageUid]);

  // Convert from local to sync when the block props change
  // EG: When UserA sets the canvas sync mode to sync
  // UserB's canvas should be converted to sync
  useEffect(() => {
    if (!pageUid || canvasSyncMode !== "local") return;

    const pullWatchProps = [
      "[:block/props]",
      `[:block/uid "${pageUid}"]`,
      (_before: PullBlock | null, after: PullBlock | null) => {
        const blockProps = normalizeProps(
          (after?.[":block/props"] || {}) as json,
        ) as Record<string, json>;
        const rjsqb = blockProps?.["roamjs-query-builder"] as Record<
          string,
          unknown
        >;
        if (rjsqb?.canvasSyncMode !== "sync") return;
        setCanvasSyncModeState("sync");
      },
    ] as const;

    window.roamAlphaAPI.data.addPullWatch(...pullWatchProps);
    return () => {
      window.roamAlphaAPI.data.removePullWatch(...pullWatchProps);
    };
  }, [canvasSyncMode, pageUid]);

  const onCanvasSyncModeChange = useCallback(
    (mode: CanvasSyncMode) => {
      const currentMigrationState = getCanvasSyncMigrationState({ pageUid });
      const nextMigrationState =
        mode === "sync" && !currentMigrationState ? "pending" : undefined;
      setCanvasSyncSettings({
        pageUid,
        mode,
        migrationState: nextMigrationState,
      });
      setCanvasSyncModeState(mode);
    },
    [pageUid],
  );

  if (useCloudflareSync) {
    return (
      <TldrawCanvasCloudflare
        title={title}
        pageUid={pageUid}
        canvasSyncMode={canvasSyncMode}
        onCanvasSyncModeChange={onCanvasSyncModeChange}
      />
    );
  }

  return (
    <TldrawCanvasRoam
      title={title}
      pageUid={pageUid}
      canvasSyncMode={canvasSyncMode}
      onCanvasSyncModeChange={onCanvasSyncModeChange}
    />
  );
};

type CanvasStoreAdapterResult = {
  store: TLStore | TLStoreWithStatus | null;
  needsUpgrade: boolean;
  performUpgrade: () => void;
  error: Error | null;
  isLoading: boolean;
};

const useRoamCanvasStore = ({
  pageUid,
  migrations,
  customShapeUtils,
  customBindingUtils,
}: CanvasStoreAdapterArgs): CanvasStoreAdapterResult => {
  const { store, needsUpgrade, performUpgrade, error } = useRoamStore({
    migrations,
    customShapeUtils,
    customBindingUtils,
    pageUid,
  });

  return {
    store,
    needsUpgrade,
    performUpgrade,
    error,
    isLoading: false,
  };
};

const useCloudflareCanvasStore = ({
  pageUid,
  migrations,
  customShapeUtils,
  customBindingUtils,
  customShapeTypes,
  customBindingTypes,
}: CanvasStoreAdapterArgs): CanvasStoreAdapterResult => {
  const { store, error, isLoading } = useCloudflareSyncStore({
    pageUid,
    migrations,
    customShapeUtils,
    customBindingUtils,
    customShapeTypes,
    customBindingTypes,
  });
  return {
    store,
    error,
    isLoading,
    needsUpgrade: false,
    performUpgrade: () => {},
  };
};

